INSERT INTO translations (lang, page, key, value) VALUES ('it', 'amici', 'intro_text', 'Sai quando dici "basta, ho bisogno di staccare"? Ecco, <strong>Casia</strong> è quel posto. Una cascina vecchia di cent''anni, sistemata come si deve, in mezzo alle colline. Niente di finto, niente di costruito per i turisti. Solo una casa vera dove il telefono prende poco e va benissimo così.') ON CONFLICT(lang, page, key) DO UPDATE SET value = excluded.value, updated_at = datetime('now');
