INSERT INTO translations (lang, page, key, value) VALUES ('fr', 'amici', 'intro_text', 'Tu sais quand tu te dis "stop, j''ai besoin de couper" ? Voilà, <strong>Casia</strong> c''est cet endroit-là. Une ferme centenaire, retapée comme il faut, au milieu des collines. Rien de faux, rien de fabriqué pour les touristes. Juste une vraie maison où le téléphone capte à peine, et c''est très bien comme ça.') ON CONFLICT(lang, page, key) DO UPDATE SET value = excluded.value, updated_at = datetime('now');
